 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; fn extract_decl_type (filename : & str) -> Option < String > { if let Some (last_part) = filename . strip_suffix (".rs") { if let Some (type_name) = last_part . split ("_decls_") . nth (1) { if type_name . starts_with ("impl_for_") { return Some ("impl" . to_string ()) ; } else if filename . contains ("_struct_") || is_likely_struct (type_name) { return Some ("struct" . to_string ()) ; } else if filename . contains ("_enum_") || is_likely_enum (type_name) { return Some ("enum" . to_string ()) ; } else if filename . contains ("_fn_") || is_likely_function (type_name) { return Some ("function" . to_string ()) ; } else if filename . contains ("_const_") || type_name . chars () . all (| c | c . is_uppercase () || c == '_') { return Some ("const" . to_string ()) ; } else if filename . contains ("_trait_") { return Some ("trait" . to_string ()) ; } else if filename . contains ("_type_") { return Some ("type" . to_string ()) ; } else if filename . contains ("_static_") { return Some ("static" . to_string ()) ; } else { return Some ("other" . to_string ()) ; } } } None }